  contractId: z.string(),
  event: z.enum(['created', 'redline']),
  title: z.string(),
  category: categorySchema,
  amountUsd: z.number(),
  text: z.string(),
});

const readContractEvent = (b: z.infer<typeof contractEvent>): SupplyOf<typeof contract> =>
