          title: b.title,
          category: b.category,
          amountUsd: b.amountUsd,
          latestRedline: b.text,
          counselNotes: '',
          draft: '',
        },
        key: b.contractId,
      }
    : { update: b.contractId, patch: { latestRedline: b.text }, state: 'received', deferred: true };

