const sharedQuota = sqlite.quota('~/.harness/shared/quota.sqlite');

const subscriptionAccounts = (maxQuotaShare: number) =>
  [1, 2, 3].map(n =>
    H.account(`claude-subscription-${n}`, claudeCode.driver({ configDir: H.env(`CLAUDE_CONFIG_DIR_${n}`) }))
