  )
  .store(trackerStore)
  .handle(buildAndAudit, {
    input: u => ({ ...u.data, rounds: 3 }),
    exits: { delivered, roundsExhausted: abandoned },
    retry: { retries: 2, backoff: { initial: '1m', factor: 2 }, exhausted: abandoned },
