    if (!response.ok) return undefined;
    return z.object({ executionId: z.string() }).parse(await response.json());
  })
  .run(async (i, ctx) => {
    const response = await fetch(`${ctx.resolve(docsUrl)}/contracts/${i.contractId}/execution`, {
